"""Build the self-contained 0.01.25 customer report from recorded evidence.

No API requests, benchmarks or production configuration changes occur here.
Accuracy and actual-network timing have independent inputs and scopes. All
customer numbers are computed from these inputs; failed probes are excluded by
the measured latency manifest, not converted to successful measurements.
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import html
import json
import math
from pathlib import Path

from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
VERSION = '0.01.25'
BASELINE = '0.01.15'


def read_json(path: Path):
    return json.loads(path.read_text(encoding='utf-8'))


def image_data(path: Path):
    with Image.open(path) as image:
        size = image.size
        assert image.format == 'PNG', f'Expected PNG: {path.name}'
    return {'image': 'data:image/png;base64,' + base64.b64encode(path.read_bytes()).decode('ascii'),
            'width': size[0], 'height': size[1],
            'sha256': hashlib.sha256(path.read_bytes()).hexdigest()}


def compact_provenance(path: Path):
    try:
        relative = path.resolve().relative_to(ROOT).as_posix()
    except ValueError:
        relative = path.name
    return {'file': relative, 'sha256': hashlib.sha256(path.read_bytes()).hexdigest()}


